/**
 * Open and resolved ownership offers. An offer stays `pending` in storage
 * after it lapses; callers decide openness from `expiresAt`.
 */
import { and, desc, eq, gt, or } from "drizzle-orm";
import { newId } from "@/lib/id";
import { getDb, ownershipHandovers } from "@/server/db";
import { toIsoTimestamp } from "@/types/common";
import { orgPredicate } from "./base-repository";
import { toOwnershipHandover } from "./_mappers";
import type { IsoTimestamp, OrgId, UserId } from "@/types/common";
import type {
  OwnershipHandover,
  OwnershipHandoverStatus,
} from "@/types/organization";

const MS_PER_DAY = 24 * 60 * 60 * 1000;
const OFFER_DAYS = 7;

export async function insertHandover(
  orgId: OrgId,
  fromUserId: UserId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  const created = new Date();
  const createdAt = toIsoTimestamp(created);
  const expiresAt = toIsoTimestamp(
    new Date(created.getTime() + OFFER_DAYS * MS_PER_DAY),
  );

  const row = getDb()
    .insert(ownershipHandovers)
    .values({
      id: newId(),
      orgId,
      fromUserId,
      toUserId,
      status: "pending",
      expiresAt,
      resolvedAt: null,
      createdAt,
      updatedAt: createdAt,
    })
    .returning()
    .get();

  return toOwnershipHandover(row);
}

/** Newest pending row in the org, including one that has already lapsed. */
export async function findLatestPending(
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .get();

  return row ? toOwnershipHandover(row) : null;
}

/** Newest offer that is still inside its seven-day window. */
export async function findOpenHandover(
  orgId: OrgId,
  now: IsoTimestamp,
): Promise<OwnershipHandover | null> {
  const row = getDb()
    .select()
    .from(ownershipHandovers)
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, now),
      ),
    )
    .orderBy(desc(ownershipHandovers.createdAt))
    .get();

  return row ? toOwnershipHandover(row) : null;
}

export async function resolveHandover(
  orgId: OrgId,
  handoverId: string,
  status: Exclude<OwnershipHandoverStatus, "pending" | "expired">,
  at: IsoTimestamp,
): Promise<OwnershipHandover> {
  const row = getDb()
    .update(ownershipHandovers)
    .set({ status, resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.id, handoverId),
      ),
    )
    .returning()
    .get();

  if (!row) throw new Error(`Ownership handover ${handoverId} not found`);
  return toOwnershipHandover(row);
}

/**
 * Withdraws every still-open offer where `userId` is either side. A lapsed
 * row is left pending so acting on it later still reports `expired`.
 */
export async function cancelOpenForUser(
  orgId: OrgId,
  userId: UserId,
  at: IsoTimestamp,
): Promise<void> {
  getDb()
    .update(ownershipHandovers)
    .set({ status: "canceled", resolvedAt: at, updatedAt: at })
    .where(
      and(
        orgPredicate(ownershipHandovers.orgId, orgId),
        eq(ownershipHandovers.status, "pending"),
        gt(ownershipHandovers.expiresAt, at),
        or(
          eq(ownershipHandovers.fromUserId, userId),
          eq(ownershipHandovers.toUserId, userId),
        ),
      ),
    )
    .run();
}

