input.new_string:
export async function resolveOrgBySlug(
  slug: string,
): Promise<Organization | null> {
  return orgRepo.findOrgBySlug(slug);
}

function denyRecordedOwner(): never {
  throw new PermissionDeniedError("org:delete", {
    action: "org:delete",
    resourceKind: "organization",
    allowed: false,
    reason: "denied_by_role",
  });
}

function assertRecordedOwner(actor: Actor, org: Organization): void {
  if (org.ownerId !== actor.userId) denyRecordedOwner();
}

function isOpenOffer(offer: OwnershipHandover, now: Date): boolean {
  return new Date(offer.expiresAt).getTime() > now.getTime();
}

/**
 * The offer the actor may still act on, or the refusal for accept/decline.
 * A lapsed offer is `expired` only for the member it was addressed to.
 */
async function requireActionableOffer(
  actor: Actor,
  orgId: OrgId,
  now: Date,
): Promise<OwnershipHandover> {
  const latest = await handoverRepo.findLatestPending(orgId);
  if (!latest || !isOpenOffer(latest, now)) {
    if (
      latest &&
      latest.toUserId === actor.userId &&
      !isOpenOffer(latest, now)
    ) {
      throw new OwnershipHandoverError("expired");
    }
    throw new OwnershipHandoverError("nothing_pending");
  }
  if (latest.toUserId !== actor.userId) {
    throw new OwnershipHandoverError("nothing_pending");
  }
  return latest;
}

export async function initiateOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
  toUserId: UserId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  if (toUserId === actor.userId) {
    throw new OwnershipHandoverError("self");
  }

  const target = await memberRepo.findMember(orgId, toUserId);
  if (!target || target.status !== "active") {
    throw new NotFoundError("Member", toUserId);
  }

  const now = toIsoTimestamp(new Date());
  const open = await handoverRepo.findOpenHandover(orgId, now);
  if (open) throw new OwnershipHandoverError("pending_exists");

  const offer = await handoverRepo.insertHandover(orgId, actor.userId, toUserId);

  await notify(orgId, "ownership_handover", [toUserId], {
    title: "You've been offered ownership of this workspace",
    body: "Accept to become the recorded owner of this workspace.",
    href: "/settings/members",
    actorId: actor.userId,
  });

  return offer;
}

export async function acceptOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<Organization> {
  assertOrgScope(actor, orgId);

  const now = new Date();
  const offer = await requireActionableOffer(actor, orgId, now);
  const acceptor = await memberRepo.findMember(orgId, actor.userId);
  if (!acceptor || acceptor.status !== "active") {
    throw new OwnershipHandoverError("nothing_pending");
  }

  const roleChanges: { memberId: string; from: Role; to: Role }[] = [];

  if (acceptor.role !== "owner") {
    const promoted = await memberRepo.updateMemberRole(orgId, acceptor.id, "owner");
    roleChanges.push({ memberId: promoted.id, from: acceptor.role, to: "owner" });
  }

  const organization = await orgRepo.setOrgOwner(orgId, actor.userId);

  const previous = await memberRepo.findMember(orgId, offer.fromUserId);
  if (
    previous &&
    previous.role === "owner" &&
    previous.userId !== actor.userId
  ) {
    const demoted = await memberRepo.updateMemberRole(orgId, previous.id, "admin");
    roleChanges.push({ memberId: demoted.id, from: "owner", to: "admin" });
  }

  const resolvedAt = toIsoTimestamp(now);
  await handoverRepo.resolveHandover(orgId, offer.id, "accepted", resolvedAt);

  for (const change of roleChanges) {
    await emit("member.role_changed", {
      ...actorEnvelope(actor),
      memberId: change.memberId as never,
      from: change.from,
      to: change.to,
    });
  }

  await emit("organization.ownership_transferred", {
    ...actorEnvelope(actor),
    fromUserId: offer.fromUserId,
    toUserId: actor.userId,
  });

  return organization;
}

export async function declineOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);
  const offer = await requireActionableOffer(actor, orgId, new Date());
  return handoverRepo.resolveHandover(
    orgId,
    offer.id,
    "declined",
    toIsoTimestamp(new Date()),
  );
}

export async function cancelOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover> {
  assertOrgScope(actor, orgId);

  const org = requireFound(
    await orgRepo.findOrgById(orgId),
    "Organization",
    orgId,
  );
  assertRecordedOwner(actor, org);

  const now = new Date();
  const latest = await handoverRepo.findLatestPending(orgId);
  if (!latest || !isOpenOffer(latest, now)) {
    throw new OwnershipHandoverError("nothing_pending");
  }

  return handoverRepo.resolveHandover(
    orgId,
    latest.id,
    "canceled",
    toIsoTimestamp(now),
  );
}

export async function getPendingOwnershipHandover(
  actor: Actor,
  orgId: OrgId,
): Promise<OwnershipHandover | null> {
  assertOrgScope(actor, orgId);
  assertCan(actor, "org:read", orgResource(orgId));
  return handoverRepo.findOpenHandover(orgId, toIsoTimestamp(new Date()));
}

